// ---- Decimal digits ----

pub(crate) fn digit_value(character: char) -> Option<u8> {
    const STARTS: &[u32] = &[
        0x30, 0x660, 0x6f0, 0x7c0, 0x966, 0x9e6, 0xa66, 0xae6, 0xb66, 0xbe6, 0xc66, 0xce6, 0xd66,
        0xde6, 0xe50, 0xed0, 0xf20, 0x1040, 0x1090, 0x17e0, 0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90,
        0x1b50, 0x1bb0, 0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0,
        0xff10, 0x104a0, 0x10d30, 0x10d40, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0, 0x11450,
        0x114d0, 0x11650, 0x116c0, 0x116d0, 0x116da, 0x11730, 0x118e0, 0x11950, 0x11bf0, 0x11c50,
        0x11d50, 0x11da0, 0x11f50, 0x16130, 0x16a60, 0x16ac0, 0x16b50, 0x16d70, 0x1ccf0, 0x1d7ce,
        0x1d7d8, 0x1d7e2, 0x1d7ec, 0x1d7f6, 0x1e140, 0x1e2f0, 0x1e4f0, 0x1e5f1, 0x1e950, 0x1fbf0,
    ];
    let point = character as u32;
    let index = STARTS.partition_point(|start| *start <= point);
    if index == 0 {
        return None;
    }
    let digit = point - STARTS[index - 1];
    (digit < 10).then_some(digit as u8)
}

// ---- Tests ----

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn unicode_folding_and_decimal_digits() {
        assert_eq!(uppercase('ᾳ'), 'ᾼ');
        assert_eq!(lowercase('İ'), 'i');
        assert_eq!(fold_character('İ'), 'İ');
        assert_eq!(fold_character('ᾼ'), 'ᾳ');
        let mut text = String::new();
        for character in "StraßeΣςİ".chars() {
            let folded = full_fold(character);
            text.extend(&folded.scalars[..folded.len]);
        }
        assert_eq!(text, "strasseσσi\u{307}");
        assert_eq!(digit_value('٣'), Some(3));
        assert_eq!(digit_value('9'), Some(9));
        assert_eq!(digit_value('Ⅷ'), None);
        assert_eq!(digit_value('²'), None);
    }
}
